    simple_clay_filtration = { name = "Preprosta glinena filtrirna naprava", clayCost = 3, glassCost = 1, time = 4, cost = 80, science = 20, happiness = 1, description = "Preprosta glinena filtrirna naprava za filtriranje." },
    brass_framed_filtration = { name = "Medeninasto okvirjena filtrirna naprava", clayCost = 2, brassCost = 2, glassCost = 1, time = 7, cost = 220, science = 35, happiness = 2, prestige = 2, description = "Medeninasto okvirjena filtrirna naprava za trgovce." },
    silver_jointed_filtration = { name = "Srebrnospojna filtrirna naprava", clayCost = 2, silverCost = 1, brassCost = 2, glassCost = 1, time = 10, cost = 540, science = 50, happiness = 2, prestige = 6, description = "Srebrnospojna filtrirna naprava za plemiče." },
    gold_trimmed_filtration = { name = "Zlatookrasna filtrirna naprava", clayCost = 2, goldCost = 1, silverCost = 1, brassCost = 2, glassCost = 1, time = 14, cost = 1300, science = 65, happiness = 3, prestige = 14, description = "Zlatookrasna filtrirna naprava za visoke plemiče." },
    jewel_valve_filtration = { name = "Draguljnoventilna filtrirna naprava", clayCost = 2, goldCost = 1, silverCost = 1, brassCost = 2, glassCost = 1, jewelCost = 1, time = 18, cost = 2900, science = 80, happiness = 5, prestige = 27, description = "Filtrirna naprava z draguljnim ventilom za visoko plemstvo." },
    royal_grand_filtration = { name = "Kraljevski veliki filtrirna naprava", clayCost = 3, goldCost = 2, silverCost = 2, brassCost = 2, glassCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 6200, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska filtrirna naprava z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    filtration_workshop = { name = "Filtrirna delavnica", cost = { gold = 280, wood = 120, stone = 140, clay = 8, glass = 6 }, upkeep = 6, qualityBonus = 5 },
    alchemy_loft = { name = "Alkemična podstrešje", cost = { gold = 1000, wood = 280, stone = 280, silver = 6, brass = 6 }, upkeep = 23, qualityBonus = 18 },
    master_filtration_atelier = { name = "Mojstrski filtrirni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_alchemy_palace = { name = "Kraljevska alkemična palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
FiltrationApparatusMaker.clayStock = 14; FiltrationApparatusMaker.glassStock = 12; FiltrationApparatusMaker.brassStock = 12; FiltrationApparatusMaker.silverStock = 6; FiltrationApparatusMaker.goldStock = 6; FiltrationApparatusMaker.jewelStock = 4; FiltrationApparatusMaker.pearlStock = 4
FiltrationApparatusMaker.productStock = {}; FiltrationApparatusMaker.buildings = {}; FiltrationApparatusMaker.maker = nil; FiltrationApparatusMaker.activeMaking = {}; FiltrationApparatusMaker.totalProducts = 0; FiltrationApparatusMaker.dayTimer = 0
function FiltrationApparatusMaker.init() FiltrationApparatusMaker.clayStock=14; FiltrationApparatusMaker.glassStock=12; FiltrationApparatusMaker.brassStock=12; FiltrationApparatusMaker.silverStock=6; FiltrationApparatusMaker.goldStock=6; FiltrationApparatusMaker.jewelStock=4; FiltrationApparatusMaker.pearlStock=4; FiltrationApparatusMaker.productStock={}; FiltrationApparatusMaker.buildings={}; FiltrationApparatusMaker.maker=nil; FiltrationApparatusMaker.activeMaking={}; FiltrationApparatusMaker.totalProducts=0; FiltrationApparatusMaker.dayTimer=0; print("[FiltrationApparatusMaker] Royal Filtration Apparatus Maker System initialized (6 products, 4 buildings)") end
function FiltrationApparatusMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FiltrationApparatusMaker.maker={name=n or ("Filtrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Filtrar najet: %s (spretnost: %d)",FiltrationApparatusMaker.maker.name,s),"success") end; return true end
function FiltrationApparatusMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FiltrationApparatusMaker.build(id) local ok,e=FiltrationApparatusMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FiltrationApparatusMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FiltrationApparatusMaker.getQualityBonus() local b=0; for _,bd in ipairs(FiltrationApparatusMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FiltrationApparatusMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and FiltrationApparatusMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.glassCost and FiltrationApparatusMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.brassCost and FiltrationApparatusMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and FiltrationApparatusMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FiltrationApparatusMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FiltrationApparatusMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FiltrationApparatusMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FiltrationApparatusMaker.buildings==0 then return false,"Potrebna filtrirna delavnica" end; if not FiltrationApparatusMaker.maker then return false,"Potreben filtrar" end; return true end
function FiltrationApparatusMaker.make(pt,qty) qty=qty or 1; local ok,e=FiltrationApparatusMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then FiltrationApparatusMaker.clayStock=FiltrationApparatusMaker.clayStock-d.clayCost*qty end; if d.glassCost then FiltrationApparatusMaker.glassStock=FiltrationApparatusMaker.glassStock-d.glassCost*qty end; if d.brassCost then FiltrationApparatusMaker.brassStock=FiltrationApparatusMaker.brassStock-d.brassCost*qty end; if d.silverCost then FiltrationApparatusMaker.silverStock=FiltrationApparatusMaker.silverStock-d.silverCost*qty end; if d.goldCost then FiltrationApparatusMaker.goldStock=FiltrationApparatusMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FiltrationApparatusMaker.jewelStock=FiltrationApparatusMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FiltrationApparatusMaker.pearlStock=FiltrationApparatusMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FiltrationApparatusMaker.maker then t=math.max(1,t-math.floor(FiltrationApparatusMaker.maker.skill/13)) end; table.insert(FiltrationApparatusMaker.activeMaking,{id="filtrationapp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FiltrationApparatusMaker.completeMaking(m) local q=1.0+(FiltrationApparatusMaker.getQualityBonus()/100); if FiltrationApparatusMaker.maker then q=q+(FiltrationApparatusMaker.maker.skill/140) end; q=math.min(2.5,q); FiltrationApparatusMaker.productStock[m.productType]=(FiltrationApparatusMaker.productStock[m.productType] or 0)+m.quantity; FiltrationApparatusMaker.totalProducts=FiltrationApparatusMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FiltrationApparatusMaker.maker then FiltrationApparatusMaker.maker.itemsMade=FiltrationApparatusMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FiltrationApparatusMaker.maker.skill=math.min(100,FiltrationApparatusMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Filtrirna naprava izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"filtrationapp.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function FiltrationApparatusMaker.update(dt) if not _G.state then return end; FiltrationApparatusMaker.dayTimer=FiltrationApparatusMaker.dayTimer+dt; if FiltrationApparatusMaker.dayTimer>=30 then FiltrationApparatusMaker.dayTimer=0; for i=#FiltrationApparatusMaker.activeMaking,1,-1 do local m=FiltrationApparatusMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FiltrationApparatusMaker.completeMaking(m); table.remove(FiltrationApparatusMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FiltrationApparatusMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FiltrationApparatusMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FiltrationApparatusMaker.getStats() return {clayStock=FiltrationApparatusMaker.clayStock,glassStock=FiltrationApparatusMaker.glassStock,brassStock=FiltrationApparatusMaker.brassStock,silverStock=FiltrationApparatusMaker.silverStock,goldStock=FiltrationApparatusMaker.goldStock,jewelStock=FiltrationApparatusMaker.jewelStock,pearlStock=FiltrationApparatusMaker.pearlStock,productStock=FiltrationApparatusMaker.productStock,numBuildings=#FiltrationApparatusMaker.buildings,hasMaker=FiltrationApparatusMaker.maker~=nil,makerName=FiltrationApparatusMaker.maker and FiltrationApparatusMaker.maker.name or "—",makerSkill=FiltrationApparatusMaker.maker and FiltrationApparatusMaker.maker.skill or 0,activeMaking=#FiltrationApparatusMaker.activeMaking,totalProducts=FiltrationApparatusMaker.totalProducts} end
return FiltrationApparatusMaker
